/* =====================================================================
   GEM TOP-UP through the admin's wallet (prepared, switched OFF by default).
   settings/wallet: the admin's payment details + packs (admin writes, all read).
   topup/{uid}: a student's requests and slip (only that student and admins read).
   The admin checks the transfer by hand; approving adds gems through the
   teacher-gift channel (adjust/{uid}), so the anti-cheat ledger stays exact.
   ===================================================================== */
var WL={cfg:{enabled:false,packs:[]},unsub:null,mine:null,mineUnsub:null,all:{},allUnsub:null};
var WALLET_METHODS=['TrueMoney Wallet','PromptPay','Bank transfer'];
Object.assign(L,{tp_chpick:m('เลือกช่องทางชำระเงิน','Choose how to pay','选择付款方式'),tp_bankx:m('โอนผ่านธนาคาร','Bank transfer','银行转账')});
function tpQrOk(X){return (typeof X==='string'&&X.length<200000&&(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+\/=]+$/.test(X)||/^\/_blob\/[A-Za-z0-9_-]{1,80}$/.test(X)))}
/* payment channels shown to students: the main account, plus an optional second one (e.g. TrueMoney + a bank) */
function tpChans(){var w=WL.cfg,a=[{method:w.method,bank:w.bank,account:w.account,accName:w.accName,qr:w.qr}];/* channel 2 shows whenever it has a QR or an account (an older save could carry on:false from before it was on by default) */if(w.ch2&&(w.ch2.account||w.ch2.qr))a.push(w.ch2);return a}
function tpChIcon(m){return m==='TrueMoney Wallet'?'👛':m==='PromptPay'?'📲':'🏦'}
function tpChName(m){return m==='Bank transfer'?t('tp_bankx'):m}
function cleanWallet(o){o=isO(o)?o:{};var c={enabled:o.enabled===true,method:WALLET_METHODS.indexOf(o.method)>=0?o.method:'TrueMoney Wallet',account:str(o.account,40),accName:str(o.accName,60),
  note:{},qr:'',packs:[]};LANGS.forEach(function(l){c.note[l]=str(isO(o.note)?o.note[l]:'',300)});
  c.bank=str(o.bank,40);var c2=isO(o.ch2)?o.ch2:{};c.ch2={on:c2.on!==false,method:WALLET_METHODS.indexOf(c2.method)>=0?c2.method:'Bank transfer',bank:str(c2.bank,40),account:str(c2.account,40),accName:str(c2.accName,60),qr:tpQrOk(c2.qr)?c2.qr:''};
  if(typeof o.qr==='string'&&o.qr.length<200000&&(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+\/=]+$/.test(o.qr)||/^\/_blob\/[A-Za-z0-9_-]{1,80}$/.test(o.qr)))c.qr=o.qr;
  if(Array.isArray(o.packs))c.packs=o.packs.filter(isO).slice(0,12).map(function(p,i){return {id:IDRE.test(p.id||'')?p.id:'p'+(i+1),gems:int(p.gems,1,1e6,10),bonus:int(p.bonus,0,1e6,0),price:int(p.price,1,1e6,10)}});
  /* promotions: first top-up bonus, the founder supporter pack, a monthly limit per student */
  c.firstPct=int(o.firstPct,0,300,50);c.spOn=o.spOn!==false;c.fdOn=o.fdOn!==false;c.fdPrice=int(o.fdPrice,1,1e5,99);c.fdGems=int(o.fdGems,0,1e6,300);
  c.fd2Price=int(o.fd2Price,1,1e5,199);SP_DEF.forEach(function(d){c[d[0]+'Price']=int(o[d[0]+'Price'],1,1e5,d[1]);c[d[0]+'Gems']=int(o[d[0]+'Gems'],0,1e6,d[2])});c.fd2Gems=int(o.fd2Gems,0,1e6,750);c.fd3Price=int(o.fd3Price,1,1e5,299);c.fd3Gems=int(o.fd3Gems,0,1e6,1300);
  c.fdUntil=typeof o.fdUntil==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(o.fdUntil)?o.fdUntil:'';c.cap=o.capV2?int(o.cap,0,1e6,0):0;c.capV2=true;
  c.waitH=int(o.waitH,0,168,24);c.terms=typeof o.terms==='string'?o.terms.slice(0,1500):'';c.hook=typeof o.hook==='string'&&TP_HOOK_RE.test(o.hook.trim())?o.hook.trim():'';
  return c}
/* three founder tiers, each once per account: id, price/gems keys in the wallet settings, exclusive crown and title */
var TP_SCRIPT="// TRI-LINGUA Quest — e-mail alert for new top-up requests\n// Sends a short e-mail to the owner of this script only. At most MAX_PER_DAY e-mails a day.\nvar MAX_PER_DAY = 50;\nfunction doPost(e) {\n  var p = {};\n  try { p = JSON.parse(e.postData.contents); } catch (err) {}\n  var props = PropertiesService.getScriptProperties();\n  var day = Utilities.formatDate(new Date(), 'Asia/Bangkok', 'yyyy-MM-dd');\n  var key = 'n_' + day, n = Number(props.getProperty(key) || 0);\n  if (n >= MAX_PER_DAY) return ContentService.createTextOutput('limit');\n  props.setProperty(key, String(n + 1));\n  function clean(v, m) { return String(v == null ? '' : v).replace(/[<>\\r\\n]/g, ' ').slice(0, m); }\n  var subject = p.test ? '[TRI-LINGUA] ทดสอบการแจ้งเตือน' : '[TRI-LINGUA] มีคำขอเติมเพชรใหม่ ฿' + clean(p.price, 8);\n  var body = (p.test ? 'การแจ้งเตือนทางอีเมลทำงานแล้ว\\n'\n      : 'นักเรียน: ' + clean(p.name, 30) + '\\nแพ็ก: ' + clean(p.pack, 60) + '\\nยอด: ฿' + clean(p.price, 8) + '\\nเพชร: ' + clean(p.gems, 10) + '\\n') +\n    '\\nตรวจสลิปและอนุมัติที่ หน้าแอดมิน → เติมเพชร\\n' + clean(p.site, 200) +\n    '\\n\\nอีเมลนี้เป็นเพียงการแจ้งเตือน กรุณาตรวจยอดเงินในแอปธนาคารก่อนอนุมัติทุกครั้ง';\n  MailApp.sendEmail(Session.getEffectiveUser().getEmail(), subject, body);\n  return ContentService.createTextOutput('ok');\n}\n";
var TP_HOOK_RE=/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]{10,120}\/exec$/;
/* e-mail alert: the teacher's own Google Apps Script web app; it only ever mails its owner, so the address is not a secret */
function tpNotify(o){var u=WL.cfg.hook;if(!u||!TP_HOOK_RE.test(u))return Promise.resolve(false);
  try{return fetch(u,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(Object.assign({site:location.origin+location.pathname},o))}).then(function(){return true},function(){return false})}catch(e){return Promise.resolve(false)}}
/* admins watch every request so the menu can show how many are waiting */
function tpWatchAll(){if(!CL.admin||!CL.db||WL.allUnsub)return;WL.allUnsub=CL.db.collection('topup').onSnapshot(function(s){var d={};s.docs.forEach(function(x){if(IDRE.test(x.id))d[x.id]=x.data()});var before=tpPendingN();WL.all=d;var now=tpPendingN();tpTitle();if(now!==before){softRender();tpBadge()}},function(){})}
function tpBadge(){var b=document.querySelector('.nav [data-act="go"][data-id="admin"]');if(!b)return;var n=tpPendingN(),el=b.querySelector('.nbadge');
  if(!n){if(el)el.remove();return}if(!el){el=document.createElement('span');el.className='nbadge';b.appendChild(el)}el.textContent=n;el.setAttribute('aria-label',n)}
function tpPendingN(){var n=0;Object.keys(WL.all||{}).forEach(function(u){var d=WL.all[u];(isO(d)&&Array.isArray(d.reqs)?d.reqs:[]).forEach(function(r){if(isO(r)&&r.st==='pending')n++})});return n}
function tpTitle(){var n=CL.admin?tpPendingN():0,base='TRI-LINGUA Quest';try{document.title=n?'('+n+') 💎 '+base:base}catch(e){}}
