function spOldList(){var o=[];Object.keys(WL.all).forEach(function(u){var d=WL.all[u],seen={};(isO(d)&&Array.isArray(d.reqs)?d.reqs:[]).filter(function(r){return isO(r)&&r.st==='ok'&&spTier(r.pack)}).sort(function(a,b){return int(a.done,0,9e15,0)-int(b.done,0,9e15,0)}).forEach(function(r){if(seen[r.pack])return;seen[r.pack]=1;if(int(r.done,0,9e15,0)<SP_UP.at&&!r.sptk){var sp=spTier(r.pack);o.push({u:u,name:str(d.name,16),rid:r.id,tk:spTk(sp),ic:sp.ic})}})});return o.filter(function(x){return x.tk>0})}
function fdOldList(){var o=[];Object.keys(WL.all).forEach(function(u){var d=WL.all[u];(isO(d)&&Array.isArray(d.reqs)?d.reqs:[]).forEach(function(r){var ft=isO(r)&&fdTier(r.pack);if(ft&&ft.tk&&r.st==='ok'&&int(r.done,0,9e15,0)<FD_UP.at&&!r.fdtk)o.push({u:u,name:str(d.name,16),rid:r.id,tk:ft.tk,ic:ft.ic})})});return o}
function prOldList(){var o=[];Object.keys(WL.all).forEach(function(u){var d=WL.all[u];(isO(d)&&Array.isArray(d.reqs)?d.reqs:[]).forEach(function(r){if(isO(r)&&r.pack==='pr1'&&r.st==='ok'&&int(r.done,0,9e15,0)<PR_UP.at&&!r.pr50)o.push({u:u,name:str(d.name,16),rid:r.id})})});return o}
function prLive(){return Date.now()<PR_TIER.until}
function prState(reqs){return fdState(reqs,'pr1')}
/* teacher side at approval: a random celestial item from the summon boxes, preferring one the student does not own yet */
function prPick(u){var pool={};(CONTENT.banners||[]).forEach(function(b){if(!b.off)(b.pool||[]).forEach(function(id){var it=ITEM[id];if(it&&it.rar==='celestial')pool[id]=1})});
  var ids=Object.keys(pool).sort();if(!ids.length)ids=ITEMS.filter(function(it){return it.rar==='celestial'&&!it.noShop}).map(function(it){return it.id});
  var pl=(CL.players||[]).filter(function(p){return p.id===u})[0],own=pl&&isO(pl.d.state)&&isO(pl.d.state.owned)?pl.d.state.owned:{},fresh=ids.filter(function(id){return !own[id]});
  var list=fresh.length?fresh:ids;return list.length?list[Math.floor(rnd(list.length))]:''}
