document.addEventListener('change',function(e){var el=e.target;if(!el)return;if(el.id==='tp_parent')UI.tpParent=el.checked;if(el.id==='tp_show')UI.tpShow=el.checked;
  if(el.name==='tp_age'){UI.tpAge=el.value;var pl=document.querySelector('.tp-parent');if(pl)pl.hidden=el.value!=='minor'}});
